  warning: {
    tri: { d: "M6.92 3.1a1.25 1.25 0 0 1 2.16 0l5 8.65a1.25 1.25 0 0 1-1.08 1.875H3a1.25 1.25 0 0 1-1.08-1.875Z" },
    stem: { d: "M8 6.25 L8 9" },
